 AlertDialog(onDismissRequest=dismiss,title={Text(stringResource(R.string.dues_payments))},text={if(payments.isEmpty())Text(stringResource(R.string.dues_no_payments))else LazyColumn{items(payments,key={it.id}){payment->ListItem(headlineContent={MoneyText(payment.amountMinor,"DZD")},supportingContent={Text(stringResource(R.string.dues_payment_line,payment.paidDate,payment.accountName))},trailingContent={if(!payment.cancelled)TextButton({pending=payment}){Text(stringResource(R.string.dues_cancel_payment))}})}}},confirmButton={TextButton(dismiss){Text(stringResource(R.string.dues_close))}})
 pending?.let{payment->BudgetConfirmationDialog(stringResource(R.string.dues_cancel_payment_title),stringResource(R.string.dues_cancel_payment_message),{vm.cancelPayment(payment.id);pending=null},{pending=null},confirmText=stringResource(R.string.dues_cancel_payment),destructive=true)}
