@Composable private fun <T> DueSelector(label:String,values:List<T>,selected:String?,id:(T)->String,text: @Composable (T) -> String,choose:(T?)->Unit){var open by remember{mutableStateOf(false)};val current=values.firstOrNull{id(it)==selected};Box{OutlinedButton({open=true},Modifier.fillMaxWidth()){Text(current?.let{text(it)}?:label)};DropdownMenu(open,{open=false}){DropdownMenuItem({Text(stringResource(R.string.dues_none))},{choose(null);open=false});values.forEach{value->DropdownMenuItem({Text(text(value))},{choose(value);open=false})}}}}
@Composable private fun statusLabel(value:DueStatus)=stringResource(when(value){DueStatus.UPCOMING->R.string.dues_status_upcoming;DueStatus.TODAY->R.string.dues_status_today;DueStatus.OVERDUE->R.string.dues_status_overdue;DueStatus.PARTIALLY_PAID->R.string.dues_status_partial;DueStatus.PAID->R.string.dues_status_paid;DueStatus.CANCELLED->R.string.dues_status_cancelled})
@Composable private fun priorityLabel(value:DuePriority)=stringResource(when(value){DuePriority.LOW->R.string.dues_priority_low;DuePriority.NORMAL->R.string.dues_priority_normal;DuePriority.HIGH->R.string.dues_priority_high;DuePriority.URGENT->R.string.dues_priority_urgent})
@Composable private fun categoryName(value:Category)=value.customName?:stringResource(R.string.dues_system_category)
private fun formatAmount(value:Long)="${value/100}.${(value%100).toString().padStart(2,'0')}"
internal fun parseAmount(value:String):Long?{val parts=value.trim().replace(',','.').split('.');if(parts.size>2||parts.any{p->p.any{!it.isDigit()}})return null;val major=parts[0].ifEmpty{"0"}.toLongOrNull()?:return null;val minor=parts.getOrNull(1).orEmpty();if(minor.length>2)return null;return runCatching{Math.addExact(Math.multiplyExact(major,100),minor.padEnd(2,'0').ifEmpty{"0"}.toLong())}.getOrNull()}
